import zipfile
import xml.etree.ElementTree as ET

NS = {
    "m": "http://schemas.openxmlformats.org/spreadsheetml/2006/main",
    "r": "http://schemas.openxmlformats.org/officeDocument/2006/relationships",
}

def col_letter_to_idx(col):
    n = 0
    for ch in col:
        n = n * 26 + (ord(ch) - ord("A") + 1)
    return n

def col_idx_to_letter(idx):
    s = ""
    while idx > 0:
        idx, rem = divmod(idx - 1, 26)
        s = chr(ord("A") + rem) + s
    return s

with zipfile.ZipFile("budget.xlsx") as z:
    names = z.namelist()
    print("ZIP entries:")
    for n in names:
        print("  ", n)
    print()

    # shared strings
    shared = []
    if "xl/sharedStrings.xml" in names:
        root = ET.fromstring(z.read("xl/sharedStrings.xml"))
        for si in root.findall("m:si", NS):
            text = "".join(t.text or "" for t in si.iter("{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t"))
            shared.append(text)

    # workbook sheet list -> rId
    wb_root = ET.fromstring(z.read("xl/workbook.xml"))
    rels_root = ET.fromstring(z.read("xl/_rels/workbook.xml.rels"))
    rel_map = {}
    for rel in rels_root.findall("{http://schemas.openxmlformats.org/package/2006/relationships}Relationship"):
        rel_map[rel.get("Id")] = rel.get("Target")

    print("Shared strings:", shared)
    print()

    for sheet in wb_root.find("m:sheets", NS):
        name = sheet.get("name")
        rid = sheet.get("{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id")
        target = rel_map.get(rid, "")
        path = "xl/" + target.lstrip("/")
        print(f"=== Sheet: {name} (target={path}) ===")
        sroot = ET.fromstring(z.read(path))
        for row in sroot.iter("{http://schemas.openxmlformats.org/spreadsheetml/2006/main}row"):
            row_num = row.get("r")
            for c in row.findall("m:c", NS):
                ref = c.get("r")
                t = c.get("t")
                v = c.find("m:v", NS)
                if v is None:
                    isel = c.find("m:is", NS)
                    val = ""
                    if isel is not None:
                        val = "".join(x.text or "" for x in isel.iter("{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t"))
                else:
                    val = v.text
                    if t == "s":
                        val = shared[int(val)]
                    elif t == "b":
                        val = val == "1"
                    elif t in (None, "n"):
                        try:
                            val = float(val)
                            if val.is_integer():
                                val = int(val)
                        except (TypeError, ValueError):
                            pass
                print(f"  {ref}: {val!r}")
        print()

